#!/usr/bin/env python3
"""Regenerate docs/API_COMPATIBILITY.md from tenscuda.api_status."""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from tenscuda.api_status import (  # noqa: E402
    CUDA_API,
    DEVICE_API,
    STATUS_MEANING,
)


def main() -> None:
    out = ROOT / "docs" / "API_COMPATIBILITY.md"
    lines = [
        "# TensCUDA API compatibility",
        "",
        "Auto-generated by `python scripts/render_api_compat.py`. Do not edit by hand.",
        "",
        "Inspired by AWS Neuron's [`torch_api_compatibility.md`](https://github.com/aws-neuron/torch-neuronx/blob/main/docs/torch_api_compatibility.md).",
        "",
        "## Status codes",
        "",
        "| Code | Meaning |",
        "|---|---|",
    ]
    for code, meaning in STATUS_MEANING.items():
        lines.append(f"| `{code}` | {meaning} |")
    lines.extend(["", "## `torch.cuda.*`", "", "| API | Status | Notes |", "|---|---|---|"])
    for name, (status, note) in sorted(CUDA_API.items()):
        lines.append(f"| `torch.cuda.{name}` | {status} | {note} |")
    lines.extend(["", "## Device remapping", "", "| API | Status | Notes |", "|---|---|---|"])
    for name, (status, note) in sorted(DEVICE_API.items()):
        lines.append(f"| {name} | {status} | {note} |")
    lines.extend([
        "",
        "## Migration logging",
        "",
        "Set `TENSCUDA_MIGRATION_LOG=1` for an exit summary, or `2` for one log line per API",
        "the first time it is touched (`mapped` / `stub` / `unsupported`).",
        "",
    ])
    out.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"wrote {out}")


if __name__ == "__main__":
    main()